constraint.script:
"def text = __context__.text if (text.length() < 2) return false
// Ignore non-literal arguments (variables, constants, function calls, etc.) if (!text.startsWith('"') && !text.startsWith("'")) return false
def inner = text[1..-2] if (inner.isEmpty()) return false
// first char is the regex delimiter char delim = inner.charAt(0) int lastDelim = inner.lastIndexOf((int) delim) if (lastDelim <= 0) return false
String flags = inner.substring(lastDelim + 1) return flags.contains('u') && flags.contains('i') && !flags.contains('r')"

"def src = tag.getAttribute("src")?.value if (src == null) return true
// internal links begin with "/", "#", "?" def external = src.startsWith("http") if (external) return false
def crossorigin = tag.getAttribute("crossorigin")?.value return crossorigin == null"

"def href = tag.getAttribute("href")?.value if (href == null) return false
// internal links begin with "/", "#", "?" def internal = href.startsWith("/") || href.startsWith("#") || href.startsWith("?") if (internal) return false
def rel = tag.getAttribute("rel")?.value return rel == null || !rel.contains("noopener") || !rel.contains("noreferrer")"

"def text = __context__.text if (text.length() < 2) return false
// Ignore non-literal arguments (variables, constants, function calls, etc.) if (!text.startsWith('"') && !text.startsWith("'")) return false
def inner = text[1..-2] if (inner.isEmpty()) return false
// first char is the regex delimiter char delim = inner.charAt(0) int lastDelim = inner.lastIndexOf((int) delim) if (lastDelim <= 0) return false
String flags = inner.substring(lastDelim + 1) return !flags.contains('u')"
